<!doctype html>
<html lang="en" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $brandName ?? 'Festiva' }} — Event Management</title>@if(!empty($brandLogo))<link rel="icon" href="{{ Storage::url($brandLogo) }}">@endif<link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/select2@4.1.0-rc.0/dist/css/select2.min.css" rel="stylesheet"><style>:root{--page:#f7f7fb;--ink:#25233a;--card:#fff;--muted:#6c757d;--line:#ece8f2}html[data-theme=dark]{--page:#15121d;--ink:#f2edf7;--card:#211c2c;--muted:#b9afc6;--line:#3c334b}body{background:var(--page);color:var(--ink);transition:.2s}.brand{background:linear-gradient(125deg,#5b2d90,#e04b70)}.hero{background:linear-gradient(115deg,#47216e,#bd4167);color:#fff;border-radius:24px}.card{background:var(--card);color:var(--ink);border:0;border-radius:18px;box-shadow:0 6px 24px #32205d19}.table{--bs-table-bg:transparent;--bs-table-color:var(--ink);--bs-table-border-color:var(--line);--bs-table-striped-color:var(--ink)}.text-muted{color:var(--muted)!important}.form-control,.form-select,.input-group-text{background:var(--card);color:var(--ink);border-color:var(--line)}.form-control:focus,.form-select:focus{background:var(--card);color:var(--ink)}.timeline{border-left:3px solid #e04b70}.timeline-item{position:relative}.timeline-item:before{content:'';position:absolute;width:14px;height:14px;border-radius:100%;background:#e04b70;left:-20px;top:24px}.nav-link{color:#e6dff4}.nav-link:hover{color:#fff}.select2-container{width:100%!important}.select2-selection{background:var(--card)!important;color:var(--ink)!important;border-color:var(--line)!important}.brand-logo{height:30px;max-width:150px;object-fit:contain}</style></head><body><nav class="navbar navbar-expand-lg brand px-3"><a class="navbar-brand text-white fw-bold d-flex align-items-center gap-2" href="{{ route('dashboard') }}">@if(!empty($brandLogo))<img class="brand-logo" src="{{ Storage::url($brandLogo) }}" alt="{{ $brandName }} logo">@else<span>✦</span>@endif <span>{{ $brandName ?? 'Festiva' }}</span></a><div class="navbar-nav ms-auto align-items-lg-center"><button id="theme-toggle" class="btn btn-sm btn-outline-light me-lg-2" type="button" title="Toggle theme"><i class="bi bi-moon-stars"></i></button><a class="nav-link" href="{{ route('masters.index','games') }}">Games</a><a class="nav-link" href="{{ route('masters.index','programs') }}">Programs</a><a class="nav-link" href="{{ route('events.index') }}">Events</a><a class="nav-link" href="{{ route('settings.edit') }}">Settings</a><form method="post" action="{{route('logout')}}">@csrf<button class="btn btn-sm btn-outline-light ms-lg-2">Sign out</button></form></div></nav><main class="container py-4">@if(session('success'))<div class="alert alert-success">{{session('success')}}</div>@endif @isset($event) @if($event->budget?->total_budget !== null && $event->grand_total > $event->budget->total_budget)<div class="alert alert-warning d-flex align-items-center gap-2"><i class="bi bi-exclamation-triangle-fill fs-5"></i><div><strong>Budget cap exceeded.</strong> This event is ₹{{number_format($event->grand_total - $event->budget->total_budget, 2)}} over the ₹{{number_format($event->budget->total_budget, 2)}} cap.</div></div>@endif @endisset @yield('content')</main><script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script src="https://cdn.jsdelivr.net/npm/select2@4.1.0-rc.0/dist/js/select2.min.js"></script><script>$('.select2').select2();const key='festiva-theme',html=document.documentElement,button=document.getElementById('theme-toggle');function theme(v){html.dataset.theme=v;button.innerHTML=v==='dark'?'<i class="bi bi-sun"></i>':'<i class="bi bi-moon-stars"></i>'}theme(localStorage.getItem(key)||'light');button.addEventListener('click',()=>{const next=html.dataset.theme==='dark'?'light':'dark';localStorage.setItem(key,next);theme(next)})</script></body></html>
